{
  "models": [
    {
      "name": "bi_customers",
      "description": "每行一部门内客户，复合键唯一；行业更新会重分组历史订单",
      "column_count": 3
    },
    {
      "name": "bi_orders",
      "description": "每行一订单；关联退款汇总和当前客户；net_revenue@1 的基础模型",
      "column_count": 10
    },
    {
      "name": "bi_refund_totals",
      "description": "原始退款先按部门和订单聚合，不能把订单实付关联到退款明细后求和",
      "column_count": 3
    }
  ]
}

{
  "name": "bi_orders",
  "columns": [
    {
      "name": "order_id",
      "type": "BIGINT",
      "description": "全局唯一订单 ID"
    },
    {
      "name": "dept_id",
      "type": "CHAR(1)",
      "description": "部门，客户和退款关联键的一部分"
    },
    {
      "name": "customer_id",
      "type": "BIGINT",
      "description": "部门内客户 ID，不能单独关联"
    },
    {
      "name": "order_date",
      "type": "DATE",
      "description": "Asia/Shanghai 业务日期，退款归属原订单日"
    },
    {
      "name": "paid_amount",
      "type": "DECIMAL",
      "description": "订单实付，人民币元，定点数"
    },
    {
      "name": "refund",
      "type": "bi_refund_totals",
      "description": "退款已按部门和订单汇总，至多一行"
    },
    {
      "name": "customer",
      "type": "bi_customers",
      "description": "按部门和客户复合键匹配当前客户，允许无匹配"
    },
    {
      "name": "refund_total",
      "type": "DECIMAL",
      "description": "订单累计已记录退款，无退款为零，归属订单日"
    },
    {
      "name": "net_amount",
      "type": "DECIMAL",
      "description": "净收入行值=实付-累计退款，人民币元；SUM 为净收入"
    },
    {
      "name": "industry",
      "type": "VARCHAR",
      "description": "客户当前行业，缺失保留订单为未知行业"
    }
  ],
  "primary_key": "order_id",
  "ref_sql": null,
  "relationships": [
    {
      "name": "orders_refund_totals",
      "models": [
        "bi_orders",
        "bi_refund_totals"
      ],
      "join_type": "MANY_TO_ONE",
      "condition": "bi_orders.dept_id = bi_refund_totals.refund_dept_id AND bi_orders.order_id = bi_refund_totals.refund_order_id"
    },
    {
      "name": "orders_customers",
      "models": [
        "bi_orders",
        "bi_customers"
      ],
      "join_type": "MANY_TO_ONE",
      "condition": "bi_orders.dept_id = bi_customers.customer_dept_id AND bi_orders.customer_id = bi_customers.customer_local_id"
    }
  ]
}

{
  "name": "bi_refund_totals",
  "columns": [
    {
      "name": "refund_dept_id",
      "type": "CHAR(1)",
      "description": "退款所属部门"
    },
    {
      "name": "refund_order_id",
      "type": "BIGINT",
      "description": "退款所属订单"
    },
    {
      "name": "refund_total",
      "type": "DECIMAL",
      "description": "订单累计退款，人民币元"
    }
  ],
  "primary_key": [
    "refund_dept_id",
    "refund_order_id"
  ],
  "ref_sql": "SELECT dept_id AS refund_dept_id, order_id AS refund_order_id, SUM(refund_amount) AS refund_total\nFROM mysql.sales.refunds\nGROUP BY dept_id, order_id",
  "relationships": [
    {
      "name": "orders_refund_totals",
      "models": [
        "bi_orders",
        "bi_refund_totals"
      ],
      "join_type": "MANY_TO_ONE",
      "condition": "bi_orders.dept_id = bi_refund_totals.refund_dept_id AND bi_orders.order_id = bi_refund_totals.refund_order_id"
    }
  ]
}

{
  "name": "bi_customers",
  "columns": [
    {
      "name": "customer_dept_id",
      "type": "CHAR(1)",
      "description": "部门，客户和退款关联键的一部分"
    },
    {
      "name": "customer_local_id",
      "type": "BIGINT",
      "description": "部门内客户 ID，不能单独关联"
    },
    {
      "name": "industry",
      "type": "VARCHAR",
      "description": "客户当前行业，不是订单时点行业"
    }
  ],
  "primary_key": [
    "customer_dept_id",
    "customer_local_id"
  ],
  "ref_sql": "SELECT dept_id AS customer_dept_id, customer_id AS customer_local_id, industry\nFROM crm.public.customers",
  "relationships": [
    {
      "name": "orders_customers",
      "models": [
        "bi_orders",
        "bi_customers"
      ],
      "join_type": "MANY_TO_ONE",
      "condition": "bi_orders.dept_id = bi_customers.customer_dept_id AND bi_orders.customer_id = bi_customers.customer_local_id"
    }
  ]
}
